-- Safety: aborts (no rows inserted) if kb_entries already has data.
-- The whole thing runs in a transaction — partial failure rolls back cleanly.

BEGIN;

-- Abort if table is non-empty so re-running won't duplicate.
DO $$
BEGIN
    IF (SELECT count(*) FROM kb_entries) > 0 THEN
        RAISE EXCEPTION 'kb_entries already has data — truncate it first or skip this seed.';
    END IF;
END $$;

INSERT INTO kb_entries (question, answer, category, products, substrates, source) VALUES
    ('Do I need to overlap the fabric reinforcement when installing it?', 'Yes. We recommend overlapping each piece of fabric by approximately 2 inches. This helps ensure continuous reinforcement, prevents weak points at seams, and improves overall durability—especially in areas prone to movement or stress.', 'Application Inquiry', ARRAY['Fabric Reinforcement']::text[], ARRAY[]::text[], 'Excel Repository'),
    ('Any exceptions to applying Fabric Reinforcement?', 'It''s not required if the surface is one sheet of metal. It is required where 2 metal corner bead surfaces meet.', 'Product Knowledge', ARRAY['Fabric Reinforcement']::text[], ARRAY['Metal']::text[], 'Excel Repository'),
    ('If I apply SEMCO liquid membrane under the x-bond Stone will it adhere with water coming through the backside?', 'If you feel that there''s an extreme amount of moisture you can pre treat with one coat of Natural Shield', 'Technical Inquiry', ARRAY['Natural Shield']::text[], ARRAY[]::text[], 'Excel Repository'),
    ('How does Natural Shield compare to Satin Stone?', 'Natural Shield is hydrophobic but won''t be resistant to oils and certain other liquids the way that Satin Stone is.', 'General Inquiry', ARRAY['Natural Shield']::text[], ARRAY[]::text[], 'Excel Repository'),
    ('Can Natural Shield be applied as a moisture mitigation barrier before other sealers?', 'Yes', 'Application Inquiry', ARRAY['Natural Shield']::text[], ARRAY[]::text[], 'Excel Repository'),
    ('Do they still have to do the 3 coats of natural shield when using it as a pre sealer?', 'Yes typically. It has to be applied to the point of rejection.', 'Application Inquiry', ARRAY['Natural Shield']::text[], ARRAY[]::text[], 'Excel Repository'),
    ('What are the application instructions for Nu-Lift Cleaner?', 'Sweep surface dampen surface with water spray the surface with the detergent solution lightly as a little goes a long way. 
Let sit for 3 to 5 minutes. 
Keep moist/spray water if it''s drying during that time. 
Lightly scrub. 
Rinse and repeat.', 'General Inquiry', ARRAY['Nu-Lift Cleaner']::text[], ARRAY[]::text[], 'Excel Repository'),
    ('Does Nu-Lift cleaner need to be diluated?', 'Nulift can be used straight or 1:1 equal parts with water.', 'Product Knowledge', ARRAY['Nu-Lift Cleaner']::text[], ARRAY[]::text[], 'Excel Repository'),
    ('What is the sq footage of 1 qt, 1 gal, & 5 gal of Nu-Lift Cleaner?', '1 Qt= 125 sq ft, 1 gal = 500 sq ft, 5 gal = 2500 sq ft', 'Product Knowledge', ARRAY['Nu-Lift Cleaner']::text[], ARRAY[]::text[], 'Excel Repository'),
    ('What does scaling mean?', '"Scale" refers to the built up mineral deposits left behind from hard water. Like the white residue on block walls and in a glass that evaporates the water out. In other areas that may be grey or other colors, Grey = magnesium build up. White = calcium build up, etc.', 'General Inquiry', ARRAY['Nu-Lift Cleaner']::text[], ARRAY[]::text[], 'Excel Repository'),
    ('How often do you need to scale a surface?', 'The frequency depends on the hardness of water & frequency of use resulting in how it builds up. It''s more frequent where there''s hard water.', 'General Inquiry', ARRAY['Nu-Lift Cleaner']::text[], ARRAY[]::text[], 'Excel Repository'),
    ('Does Polar Bear contain Yellow Oxide?', 'No', 'Product Knowledge', ARRAY['Raw Pigment']::text[], ARRAY[]::text[], 'Excel Repository'),
    ('What is the closest match to SW 0055: Light French Gray?', 'In SEMCO Colors, the closest match would be Smoky Silhouette 2955P.', 'Product Knowledge', ARRAY['Raw Pigment']::text[], ARRAY[]::text[], 'Excel Repository'),
    ('Do you have to add the color activators when pigmenting the x- bond liquid? For instance whether I use your pigment or my own i still need the activator in combination with the pigment regardless? Can I tint the X bond without the color activators only using my own colorants?', 'Yes, the way to integrally color X-Bond Microcement is to tint/add pigment to the X-Bond Liquid. You are welcome to test your own colorants, water based universal pigments.', 'General Inquiry', ARRAY['Raw Pigment']::text[], ARRAY[]::text[], 'Excel Repository'),
    ('What do you do when you get bubbles in one section of satin stone?', 'Sand off 60 or 80 grit sandpaper and reapply.', 'Application Inquiry', ARRAY['Satin Stone']::text[], ARRAY[]::text[], 'Excel Repository'),
    ('Is Satin Stone 100% solids?', 'No, it is 55% solids.', 'Product Knowledge', ARRAY['Satin Stone']::text[], ARRAY[]::text[], 'Excel Repository'),
    ('do we have recommendations on brands or specifics for airless sprayers for tinted satin?', 'Graco or Titan airless sprayers are good brands. The most important part is the tip size, 5-20for exteriors', 'Product Knowledge', ARRAY['Satin Stone']::text[], ARRAY[]::text[], 'Excel Repository'),
    ('Does using double pigment color activators degrade the quality of Satin Stone sealer?', 'No, it overall just makes it a bit thicker. In terms of square feet it still needs to be used at the 200 - 250 sq ft coverage range', 'Product Knowledge', ARRAY['Satin Stone']::text[], ARRAY[]::text[], 'Excel Repository'),
    ('If I used another microcement, can I use the Satin Stone on top?', 'Yes', 'Technical Inquiry', ARRAY['Satin Stone']::text[], ARRAY[]::text[], 'Excel Repository'),
    ('What is the minimum thickness requirement of Satin Stone?', '20 mils', 'Product Knowledge', ARRAY['Satin Stone']::text[], ARRAY[]::text[], 'Excel Repository'),
    ('Can Satin Stone be applied over a 2 part epoxy?', 'Yes, it can be applied over another sealer.  Once dried, scuff sealer with a 60-grit sandpaper, and apply Satin Stone. Test a small area first as various resins may differ. Once it hits 75% cure your good to go. It will reduce the sheen to a satin.', 'Application Inquiry', ARRAY['Satin Stone']::text[], ARRAY['Epoxy']::text[], 'Excel Repository'),
    ('For the Semco Satin Stone sealer, can that go over a water based polyurethane?', 'A water based urethane isn''t typically a sound substrate and it''s weaker than the Satin Stone. It''s recommended to remove it with light sanding or Semco''s Power Cleaner detergent, prior to applying Satin Stone', 'Application Inquiry', ARRAY['Satin Stone']::text[], ARRAY['Water based polyurethane']::text[], 'Excel Repository'),
    ('If the satin stone part b expands, is it usable?', 'Yes, it is still usable. Just poke a small hole in the corner to let some of the air out.', 'General Inquiry', ARRAY['Satin Stone']::text[], ARRAY[]::text[], 'Excel Repository'),
    ('Someone applied Satin Stone on granite and got bubbles on the surface. I am waiting for their method and process but do we already know what these kinds of bubbles can indicate?', 'Bubbles can occur when apply a single coat to heavy, or a second coat too fast/soon. Granite is a very nonporous surface and satin has a high viscocity. If applied thick, there is no where for the moisture to go when curing. The key is very thin coats.', 'Technical Inquiry', ARRAY['Satin Stone']::text[], ARRAY['Granite']::text[], 'Excel Repository'),
    ('Do we know I''d SLM is food grade, for drinking water storage?', 'No, SEMCO Liquid Membrane is not for storing drinking water.', 'Product Knowledge', ARRAY['SEMCO Liquid Membrane']::text[], ARRAY[]::text[], 'Excel Repository'),
    ('Is the SEMCO Liquid Membrane still good to be used as it has frozen?', 'Wait for it to thaw and give it a good mix.  If it does not look separated, it is good for use.', 'Technical Inquiry', ARRAY['SEMCO Liquid Membrane']::text[], ARRAY[]::text[], 'Excel Repository'),
    ('Can we apply SLM and satin stone directly to an existing elastometric after roughing it up?', 'If not delaminating, proceed with sanding/profiling with a 60-grit sandpaper. Perform Prep C for outside applications; perform Prep B for inside applications.', 'Application Inquiry', ARRAY['SEMCO Liquid Membrane']::text[], ARRAY['Elastometric']::text[], 'Excel Repository'),
    ('Does Stone Soap need to be completely washed out before proceeding with application?', 'Yes, clean off all Stone Soap residue or it will look white and can affect the bonding of you sealer.', 'Product Knowledge', ARRAY['Stone Soap']::text[], ARRAY[]::text[], 'Excel Repository'),
    ('What is the best sealer to use on wood that was colored with color grain?', 'Titan Shield is recommended for application over wood.', 'Application Inquiry', ARRAY['Titan Shield']::text[], ARRAY['Wood']::text[], 'Excel Repository'),
    ('Are three coats of Titan Shield required?', 'Without 3 coats minimum it will flake.', 'Product Knowledge', ARRAY['Titan Shield']::text[], ARRAY[]::text[], 'Excel Repository'),
    ('What is the minimum thickness requirement of Titan Shield?', '6 to 8 mils', 'Product Knowledge', ARRAY['Titan Shield']::text[], ARRAY[]::text[], 'Excel Repository'),
    ('What happens if the X-Bond Liquid freezes?', 'Should X-Bond Liquid freeze, it may still be usable. To determine, the process is put a shearing blade on a drill and blend. After mixing, transfer to a second container and use a strainer to confirm there if there is little to no separated material.', 'Technical Inquiry', ARRAY['X-Bond Liquid']::text[], ARRAY[]::text[], 'Excel Repository'),
    ('Does anyone use the xbond liquid itself as a pre sealer/conditioner before the satin stone?', 'No', 'Application Inquiry', ARRAY['X-Bond Liquid']::text[], ARRAY[]::text[], 'Excel Repository'),
    ('Can Microbond be used in pool applications?', 'Also do not use micro bond in pool applications nor over polishing the X-Bond as this may cause bubbles in the coating.', 'Application Inquiry', ARRAY['X-Bond Seamless Stone']::text[], ARRAY['Pool']::text[], 'Excel Repository'),
    ('How do you suggest removing the X-Bond as recommended? Do you guys have experience with this and what type of tools or equipment is best?', 'For tools removing : probably something like a putty knife to remove all the loose parts and then as for the rest grinding it off.', 'Application Inquiry', ARRAY['X-Bond Seamless Stone']::text[], ARRAY[]::text[], 'Excel Repository'),
    ('What does it mean to ''terminate'' X-Bond?', 'Terminations are usually the architects call, we never made them (architect/designer) because we don’t decide it.', 'Application Inquiry', ARRAY['X-Bond Seamless Stone']::text[], ARRAY[]::text[], 'Excel Repository'),
    ('Is it okay to apply X-Bond with dry tools?', 'Never apply X-Bond with dry tools. Have a nearby bin of water, to rinse your tools during installation, as the materials stick to the tool. That’s ok, just shake off excess water and proceed.', 'Application Inquiry', ARRAY['X-Bond Seamless Stone']::text[], ARRAY[]::text[], 'Excel Repository'),
    ('How tight should you apply the Scratch Coat?', 'this is really tight, like 1/32” – this is our bond coat. Do not alter. Make small batches.', 'Application Inquiry', ARRAY['X-Bond Seamless Stone']::text[], ARRAY[]::text[], 'Excel Repository'),
    ('Is there a specific method to mix the X-Bond?', 'do not heat up the mixture with too fast a drill. After adding Stone you may want to do short buzzes to mix, stop and scrape down sides, repeat... instead of just running the drill in it.', 'Application Inquiry', ARRAY['X-Bond Seamless Stone']::text[], ARRAY[]::text[], 'Excel Repository'),
    ('Can it be applied inside a fireplace?', 'it’s not recommended cause it will discolor and char like any other cementious product, however it will not burst into flames or procreate a fire, so can it, yes, do I like it, no. But if someone wants to put it in the fireplace know that zero warranty will be offered.', 'Application Inquiry', ARRAY['X-Bond Seamless Stone']::text[], ARRAY['Fireplace']::text[], 'Excel Repository'),
    ('What is the best texture to use in a bathroom?', 'X-Bond Vellum', 'Application Inquiry', ARRAY['X-Bond Seamless Stone']::text[], ARRAY[]::text[], 'Excel Repository'),
    ('Trying your Semco product on a 1,200SF pool we are renovating. The pool surface is sprayed with a product, M395, this product is a polyurea. What would be the process to apply X-Bond on polyurea?', 'Sand with a 60 grit Prep D Full X-Bond Application I don’t believe they’ll need the SLM because of the Poly that’s already on there, if its still in good condition then there should be no leaking issues.', 'Application Inquiry', ARRAY['X-Bond Seamless Stone']::text[], ARRAY['Pool']::text[], 'Excel Repository'),
    ('How is texture determined?', 'Texture is determined by how tightly the product is troweled and whether or not Microbond is used.', 'Product Knowledge', ARRAY['X-Bond Seamless Stone']::text[], ARRAY[]::text[], 'Excel Repository'),
    ('What are the differences with the old texture applications vs new?', 'X-Bond Solid = Color bond NO MICRO, BUT PAINTED SOLID WITH TINTED SEALER X-Bond Polished = Polished Bond WITH OR WITHOUT MICRO - JUST WET TROWEL IT X-Bond Grain = Natural Grain Additional Notes: The change is that designers want less movement and variation than in the past. Corsa = With Microbond (for clients looking for plaster/ultra smooth) Vellum - Without Microbond (like Colorbond) Even with these 2 we tint sealer and fog in the first coat to bring color to where they want it and then proceed with clear, instead of painting is like XB Solid.', 'Product Knowledge', ARRAY['X-Bond Seamless Stone']::text[], ARRAY[]::text[], 'Excel Repository'),
    ('What is the average thickness?', 'The average system thickness is 1/8" to 1/4".', 'Product Knowledge', ARRAY['X-Bond Seamless Stone']::text[], ARRAY[]::text[], 'Excel Repository'),
    ('Tiled Bathrooms', 'For tiled bathrooms, It is important to find out the size of the tile as smaller tiles require more brown coat as there is more grout to fill. Larger tiles do not use as much brown coat.', 'Product Knowledge', ARRAY['X-Bond Seamless Stone']::text[], ARRAY['Tile']::text[], 'Excel Repository'),
    ('What is a material cost range for DIY projects?', 'A good range to recommend is $5.50 to $8-9 a sq ft. Smaller projects tend to use closer to the $8-9 range while larger projects use closer to the $5.50 as you will not have as much leftovers. I, personally feel like brown coat is outside of our averages and it leaves the wrong impression to potential clients that don''t know what we are yet. Average thickness is 1/8"-3/16" Depending on if it''s Vellum or Corsa. I say $3.50-$5.50 because it covers the general range of above with our Satin Stone, most expensive sealer. I state it as $3.50-$5.50/sf for our average applications or I''ll be specific with the thickness 1/8-3/16". That leaves it open to understand that thicker cost more, without leaving the initial impression to be that high for just materials.', 'Product Knowledge', ARRAY['X-Bond Seamless Stone']::text[], ARRAY[]::text[], 'Excel Repository'),
    ('Just confirming if the xbond has too much movement and it has been sealed already on walls that they can do a light sand and go back over it with microbond with a squeegee to create less movement and more of a consistent color like in that video that Meena (sp?) does on the Semco youtube entitled "wall application".', 'Hi Alex, Yes, that is doable: Sand surface with a 60 grit sand paper, ensuring to remove as much as the sealer as possible Clean debris Primer with X-Bond Liquid (Colored in the color for the surface) Apply the microbond with the normal 1:2 ratio Allow to dry 24 hours/next day before sealing', 'Technical Inquiry', ARRAY['X-Bond Seamless Stone']::text[], ARRAY[]::text[], 'Excel Repository'),
    ('If they use clear primer it will be lighter, right? I am concerned it will be a lot darker if they use it and it will be hard to match', 'Might make it a bit darker, but when using an uncolored primer you may still have the undesired variation', 'Technical Inquiry', ARRAY['X-Bond Seamless Stone']::text[], ARRAY[]::text[], 'Excel Repository'),
    ('if X-Bond Microcement is used as underlayment for tile, do we advise to keep it u sealed?', 'Unsealed', 'Product Knowledge', ARRAY['X-Bond Seamless Stone']::text[], ARRAY[]::text[], 'Excel Repository'),
    ('Like, is the satin thicker in wet mils and more liquid cures off Whereas the titan needs less wet mils because the single part product has less water curing out....?', 'That''s correct. Satin has a lot higher solids content too.', 'Product Knowledge', ARRAY['X-Bond Seamless Stone']::text[], ARRAY[]::text[], 'Excel Repository'),
    ('Cleaners that can strip the floor', 'Ajax', 'Product Knowledge', ARRAY['X-Bond Seamless Stone']::text[], ARRAY[]::text[], 'Excel Repository'),
    ('We have some extra Semco product left over from the project that’s still unopened, and we wanted to ask if it has an expiration date.', 'Anything that isn''t mixed with color can go up to 3 years, sealed and stored in a temperate and dark location. Our pigments are organic. If it smells rotten, it is.', 'Product Knowledge', ARRAY['X-Bond Seamless Stone']::text[], ARRAY[]::text[], 'Excel Repository'),
    ('Also, is there any way to make the finish appear whiter or less grey? Maybe something we can add to the mixture?', 'The integral color for X-Bond can go Blanco double pigment AND you can pigment the sealer and fog it in a faux finishing manner to mute trowel marks and the sand aggregate in the dry part of the mixture.', 'Product Knowledge', ARRAY['X-Bond Seamless Stone']::text[], ARRAY[]::text[], 'Excel Repository'),
    ('In what type of container is X-bond delivered?', 'X-Bond is not mixed with water. The liquid polymer gives 3x the flexibility, which will be helpful in your moving vehicle. 50 lb bags XB Stone, 1 or 5 gal buckets XB Liquid with color, sealer is quarts or gallons, depending on selection. The Kerdi and our steps of Semco Liquid Membrane and fabric reinforcement could be considered duplicitous. I know our products have HIGH flexibiity, good for vibrations. I can''t speak for Kerdi. It''s your call. Detail: https://semco-surfaces.squarespace.com/s/Shower-Detail-Concrete.pdf', 'General Inquiry', ARRAY['X-Bond Seamless Stone']::text[], ARRAY[]::text[], 'Excel Repository'),
    ('What tools are required for application of X-bond?', 'concrete broom, hand trowels, margin trowels, buckets, mixing drill or hand mixing, measuring containers, roller and tray, optional sprayers, optional sandpaper. Most are seen here: https://www.youtube.com/watch?v=_Bi9KJeB_Js&list=PLNxu5R0GgWpUWCwJi_DHXkBDqOG4lv8eK&index=1&pp=iAQB', 'General Inquiry', ARRAY['X-Bond Seamless Stone']::text[], ARRAY[]::text[], 'Excel Repository'),
    ('Does X-bond contain portland cement?', 'Some', 'General Inquiry', ARRAY['X-Bond Seamless Stone']::text[], ARRAY[]::text[], 'Excel Repository'),
    ('What is the cure time when using X-Bond Microcement in a pool?', 'Up to 5 days', 'Product Knowledge', ARRAY['X-Bond Seamless Stone']::text[], ARRAY['Pool']::text[], 'Excel Repository'),
    ('Is X-Bond Microcement compatible with the Schluter DITRA-HEAT shower system?', 'Regarding the shower system, you''re right; our product does serve as multiple waterproofing layers, making the Schluter system potentially redundant. However, it depends on the specific details of your project and local building codes.', 'General Inquiry', ARRAY['X-Bond Seamless Stone']::text[], ARRAY[]::text[], 'Excel Repository'),
    ('New contractor customer, was trying to match baked clay based on a picture. He did not use Microbond, could that be why this looks a little greyer? I am thinking the solution is to just get him some microbond so there is a higher proportion of pigment in the mix at 1:2. He thinks he got phantom pigment despite the fact that it says baked clay on the container. Thoughts?', 'Hi, several factors could be at play, the Micro can be a solution, also remind them that using the colored XB liquid when priming will make it potentially darker too', 'Technical Inquiry', ARRAY['X-Bond Seamless Stone']::text[], ARRAY[]::text[], 'Excel Repository'),
    ('What is Corsa comparable to?', 'Corsa is superfine and comes out looking like plaster/tadelakt/limewash/etc.', 'Product Knowledge', ARRAY['X-Bond Seamless Stone']::text[], ARRAY[]::text[], 'Excel Repository'),
    ('I''m just double checking to see if this Starter Kit that you have listed for me is the fine texture one or the material that will give me the smoothest surface.', 'The kit is designed to let you test out "everything," in the following sense: All X-Bond Microcement textures start as Vellum, it''s the literal base model. An additional ultrafine Microbond powder is used on top to create Corsa. The kit includes some. The kit that includes colored Titan, allows you to further control color topically and mute markings you don''t want to see. If you use colored Titan heavily you end up at X-Bond Solid. The kit without Colored Titan will take you all the way to finish with matte sealer for Corsa and/or Vellum.', 'Product Knowledge', ARRAY['X-Bond Seamless Stone']::text[], ARRAY[]::text[], 'Excel Repository'),
    ('How do you apply the full system of XB Microcement and SEMCO Liquid Membrane?', 'When applying the full system of XB Microcement and Semco Liquid Membrnae, to tile, you''d follow the same detail as a shower: https://semco-surfaces.squarespace.com/s/Shower-Detail.pdf *Please note* Scratch coat, the brown coat to level the tile, and the X-Bond Finish coats are ALL X-BOND.', 'Application Inquiry', ARRAY['X-Bond Seamless Stone']::text[], ARRAY[]::text[], 'Excel Repository'),
    ('Is it possible to "roll on" the scratch coat and other parts of the system on the floor?', 'Scratch coat is your bond coat. Do not Alter. You can try whatever you like but we don''t roll X-Bond. We trowel it on. If you''re experimenting, keep your batch mixes around 1 part liquid to 2.5 stone and keep each coat under 1/8" to avoid crazing.', 'Application Inquiry', ARRAY['X-Bond Seamless Stone']::text[], ARRAY[]::text[], 'Excel Repository'),
    ('Do you need the fabric to tie in any corners or joints? Are grout joints considered joints? We did just install new epoxy grout. Honestly, at this moment I don''t even care if we still see the tile grout lines once the product is finished, just trying to waterproof the area and make it look like one color is the goal. I wanted to make sure the product can be over epoxy grout, the porcelain tile are a full body tile, no glaze...', 'Grout between tile is not the same as joints. You would follow the tile detail we provided. If you want to save money you can skip the brown coat, and then the lines will come back from the existing grout, as it cures. X-Bond and Semco Liquid Membrane are both waterproofing layers. It''s still the installer''s responsibility to ensure there are no areas of penetration for moisture. If you have photos of the area, feel free to send them over, in order for me to see if there''s anything else to cover.', 'Application Inquiry', ARRAY['X-Bond Seamless Stone']::text[], ARRAY[]::text[], 'Excel Repository'),
    ('difference corsa / velum, is one recommended over other in bathroom?', 'Vellum is the start of all of the textures. Smooth like microcement with slight texture. 1/8". Corsa has an additional ultra fine layer so it''s ultra smooth like a plaster, brings it to 3/16"', 'Product Knowledge', ARRAY['X-Bond Seamless Stone']::text[], ARRAY[]::text[], 'Excel Repository'),
    ('plumbing requirements (hot mob, plumbing distance out wall)', 'This is a coating. We don''t have requirements, typically. You''d present what you have and we''d guide you to any slight adjustments.', 'Application Inquiry', ARRAY['X-Bond Seamless Stone']::text[], ARRAY[]::text[], 'Excel Repository'),
    ('What do you do if there are no installers in the area?', 'Alternatively, if you know any local plasterers or coatings installers, even stucco installers, you can put them in touch with me. They''d have the skill set to apply our materials and you''d save money by hiring them with a day rate and buying materials directly from us, the manufacturer.', 'Application Inquiry', ARRAY['X-Bond Seamless Stone']::text[], ARRAY[]::text[], 'Excel Repository'),
    ('How do we remove SLM on Pebble Tech once it has cured?', 'Prep B, but that may also affect the resin used on the pebble tech too its best they ask the supplier or manufacturer of that what chemicals are suitable for removing a waterbed elasticmeric from he top', 'Technical Inquiry', ARRAY['X-Bond Seamless Stone']::text[], ARRAY[]::text[], 'Excel Repository'),
    ('Is there some sort of technique that would be used on the shower floor, to reduce slipperyness? Or is it not that slippery when wet? What is typically done for that?', 'How smooth or textured you apply it is up to you. It''s only slippery if you trowel or sand it extra smooth. That''s the best way to make it look natural. Alternatively, you can request we add non skid additive to the order for you to add to the sealer, which will require you to spray it to make it look more even.', 'Technical Inquiry', ARRAY['X-Bond Seamless Stone']::text[], ARRAY[]::text[], 'Excel Repository'),
    ('Can I get a set of samples that shows the color options? So I can put it on the wall in the bathroom to ensure we get the right color.', 'X-Bond has too many custom options and colors. We don''t provide full sets of samples to anyone, including contractors, and designers. The awarded installer is to make the submittal samples. If it''s a DIY, that''s you. We''ll provide 1 or 2 if they''re in stock.', 'General Inquiry', ARRAY['X-Bond Seamless Stone']::text[], ARRAY[]::text[], 'Excel Repository'),
    ('Are the baseboards typically removed? And what type of outlet covers do people tend to use with this design aesthetic ?', 'As they would say here, in Las Vegas, those are both dealer''s choice. Some people like baseboards and others prefer a seamless look with a fluid cove where our product just goes from floor to wall, or turns a corner with a clean, right angle.', 'Application Inquiry', ARRAY['X-Bond Seamless Stone']::text[], ARRAY[]::text[], 'Excel Repository'),
    ('Would we be able to cover a pre-fab tub?', 'Any hard surface as long as it''s clean and pH neutral. Any use type; floors to ceiling, interior/exterior, showers/pools/tubs, etc.', 'Application Inquiry', ARRAY['X-Bond Seamless Stone']::text[], ARRAY[]::text[], 'Excel Repository'),
    ('so it''s in a Liquitex- like base? I add that for tinting to my quick set cement...also ...is this sandable?', 'My personal experience with Liquitex is from art and craft stores. X-Bond is an industrial grade product comprised of XB Stone and XB Liquid, which is white to start and where we put the integral color. I''m reachable on my cell if you want to discuss this more. I don''t have enough data to answer you. Sanding - Yes!', 'General Inquiry', ARRAY['X-Bond Seamless Stone']::text[], ARRAY[]::text[], 'Excel Repository'),
    ('Do you have samples? How much is the shipping for say, 25 pounds?', 'Hard samples are currently a commodity with our current level of growth, and reserved for architects and designers only. Contractors and applicators make their own as the product is completely customized with your trowel work and creativity. It''s a system, not a dry mix you add water to so you can''t just "buy 25 lbs." The good news is that the X-Bond Liquid is why X-Bond Microcement has 3x the flexibility of water mixes, is intrinsically waterproof, and has a chemical bond to ANY HARD SURFACE. We do offer kits starting with 25 lbs of X-Bond Stone and the components that go with it. If you''d like a quote please provide your shipping address. I get that you''re an artist and not a contractor who would be more interested in standard practices. If you want to navigate options, give me a call or I''ll be typing for eternity.', 'General Inquiry', ARRAY['X-Bond Seamless Stone']::text[], ARRAY[]::text[], 'Excel Repository'),
    ('Additionally, we are exploring microcement for use in an indoor pool deck area and sauna space, is there a particular Semco product line or finish that is best suited for these types of wet areas?', 'For a casino or hotel pool deck, we''d recommend our X-Bond Microcement in the ADA Safety Floor texture: https://www.semcosurfaces.com/ada-safety-floor But, I believe Lifetime would want something more....elegant. That would be a variation of our Vellum with heavier trowel texture.', 'General Inquiry', ARRAY['X-Bond Seamless Stone']::text[], ARRAY[]::text[], 'Excel Repository'),
    ('Does the X-Bond microcement product have any issues with staining at shower wall locations?', 'Not if it''s sealed per our requirements. Sealer is part of the system and always quoted with, unless you request otherwise.', 'Application Inquiry', ARRAY['X-Bond Seamless Stone']::text[], ARRAY[]::text[], 'Excel Repository'),
    ('Is there any additional sealer product needed for wet locations?', 'Semco Satin Stone for Matte Finish or Titan Shield Gloss for gloss. Info on both here: https://www.semcosurfaces.com/sealers Please note how Satin Stone''s page says it''s got minimum 10 years before you do anything. I believe most plasters need to be touched every 6 months or so.', 'Application Inquiry', ARRAY['X-Bond Seamless Stone']::text[], ARRAY[]::text[], 'Excel Repository'),
    ('Are there special maintenance requirements for microcement above and beyond what would normally be required for other finishes such as tile?', 'Use a pH neutral detergent like Simple Green. We make Stone Soap. We recommend de scaling occasionally. We offer Nulift for that. There''s no major maintenance.', 'Application Inquiry', ARRAY['X-Bond Seamless Stone']::text[], ARRAY[]::text[], 'Excel Repository'),
    ('Would it be correct to specify first using a self-leveling compound on top of the original slab and then to apply the Microcement on top of that?', 'How far out of level is the surface? If it''s a lot then, yes, use a self leveler first to be more cost effective. If it''s light (like 1/4") stick with the X-Bond Microcement Brown Coat to float to level.', 'Application Inquiry', ARRAY['X-Bond Seamless Stone']::text[], ARRAY[]::text[], 'Excel Repository'),
    ('Is the X-Bond System rated for freeze thaw durability in extreme climates?', 'Yes. Between the permanent chemical bond, no porosity for water to get into and freeze, and the extremely high polymer content = extreme flexibility to move with the substrate.', 'Product Knowledge', ARRAY['X-Bond Seamless Stone']::text[], ARRAY[]::text[], 'Excel Repository'),
    ('How does the system hold up against salts, cars with studded tires, snow plows, and heavy tire traffic?', 'Heavy Tires, great. See firetruck bay case study: https://www.semcosurfaces.com/case-studies/las-vegas-fire-and-rescue-station-3-commercial Studded Tires/Chains & Plows, this will come down to how hard is the substrate, and how these things are used. It''s called X-Bond because it bonds to X but it''s only an 1/8" coating.', 'Product Knowledge', ARRAY['X-Bond Seamless Stone']::text[], ARRAY[]::text[], 'Excel Repository'),
    ('Would the anti-slip finish be the best option for this application? Would the troweled application be slick when wet, causing cars to slide and people to slip?', 'X-Bond Can be applied as smooth or rough as you like. The Vellum version can be done with more texturing [trowel it like any cementitious coating] or you can go with the ADA Safety floor version for maximum slip resistance. https://www.semcosurfaces.com/ada-safety-floor', 'Application Inquiry', ARRAY['X-Bond Seamless Stone']::text[], ARRAY[]::text[], 'Excel Repository'),
    ('Are there any special maintenance recommendations or limitations specific to a driveway in our mountain environment?', 'See attached which is a suggestion. Note, X-Bond is basically seamless. There are no pores for minerals or anything to hide in creating an acceptable patina. Stone Soap is simply a pH neutral detergent. You can use something similar. Nulift is used typically after the Spring rains if you have salt and efflorescence build up to remove.', 'Product Knowledge', ARRAY['X-Bond Seamless Stone']::text[], ARRAY[]::text[], 'Excel Repository'),
    ('Are there any scenarios which would void warranty that we should be aware of?', 'Improper application, not following order of operations, dirty or non pH balanced substrate, wrong mixing ratios. Semco is wide open on options for substrates and types of use, including driveways.', 'Product Knowledge', ARRAY['X-Bond Seamless Stone']::text[], ARRAY[]::text[], 'Excel Repository'),
    ('Can you explain: Are there any scenarios which would void warranty that we should be aware of?', 'Improper application, not following order of operations, dirty or non pH balanced substrate, wrong mixing ratios. Semco is wide open on options for substrates and types of use, including driveways.', 'Product Knowledge', ARRAY['X-Bond Seamless Stone']::text[], ARRAY[]::text[], 'Excel Repository'),
    ('What is the recommendation for are there any scenarios which would void warranty that we should be aware of?', 'Improper application, not following order of operations, dirty or non pH balanced substrate, wrong mixing ratios. Semco is wide open on options for substrates and types of use, including driveways.', 'Product Knowledge', ARRAY['X-Bond Seamless Stone']::text[], ARRAY[]::text[], 'Excel Repository'),
    ('I want to know typically how long it will take to apply/finish the entire system in days and how many installers working on the job.', 'Typically, for a project of this size (489 sq ft), the application of X-Bond Microcement Corsa takes approximately 3-5 days, assuming mininum 1 main applicator, and 1 to 2 helpers to mix batches/runner/clean up. You''ll need the 3rd guy if you choose to use a hopper gun, but the application will go much faster if you don''t have experienced plasterers.', 'Application Inquiry', ARRAY['X-Bond Seamless Stone']::text[], ARRAY[]::text[], 'Excel Repository'),
    ('If my shower walls are going to have tile floors and semco on the walls/ceiling.. is there a recommendation for the transition from floor to walls? do you put a reglet or run the corsa right down to touch the tile floor?', 'Going from one hard surface to another you can butt right up to the tile with X-Bond Microcement, like I did in my own home. If there are open edges use a silicone bead to terminate and ensure no points of moisture penetration. From a design standpoint if you want to use some kind of transition strip you can use ANYTHING (metal, pvc, etc.) as X-Bond bonds to all surfaces chemically [while remaining a water based product], not via adhesion.', 'Application Inquiry', ARRAY['X-Bond Seamless Stone']::text[], ARRAY[]::text[], 'Excel Repository'),
    ('Any water proofing recommendation with that condition?', 'The typical silicone bead would cover this for X-Bond''s finished and exposed edges. Internally our system provides 3 rounds of waterproofing per this detail: https://www.semcosurfaces.com/s/Shower-Detail-Concrete.pdf The X-Bond, Semco Liquid Membrane and fabric reinforcement are all waterproof. You have to decide if you''ll have our process withe the corner fabric taping done first so that the tile can overlap our waterproofing (the orange and blue sections of the detail with the blue coming down to the floor, under the tile). If you don''t, you''d be leaning on any other waterproofing you specify and/or the silicone bead.', 'Application Inquiry', ARRAY['X-Bond Seamless Stone']::text[], ARRAY[]::text[], 'Excel Repository'),
    ('Examples for responding with needing to smooth out or cover up something being solved with sanding/tinting sealer:', 'They don''t like the current texture. Someone put a footprint in wet sealer Dust in the sealer. Tiny bubbles showed up in the top of Microbond. Discoloration from xb or sealer getting wet before cure. Just about any kind of discoloration where they product (XB and Satin) is still working but the coloring is blemished in some way. Tiny bubbles in curing sealer that don''t cure out. They show up as a white or light colored haze in areas. On light greys it''s not as noticeable as on darker colors.', 'Technical Inquiry', ARRAY['X-Bond Seamless Stone']::text[], ARRAY[]::text[], 'Excel Repository'),
    ('Customer had cracks after applying Vellour Smooth. Steps on how to fix the cracks', 'The visible cracks can be addressed using the following method: Clean the affected joint thoroughly, Prime the area with X-Bond Liquid, Prepare a repair mixture using 1 part X-Bond Stone to 2 parts X-Bond Liquid, Use a sponge to work the mixture into the crack.', 'Technical Inquiry', ARRAY['X-Bond Seamless Stone']::text[], ARRAY[]::text[], 'Excel Repository'),
    ('can we use you product over schluter heated floor system. How thick can we go with your product.', 'Are you using electrical with a mat system that takes about 1/4" to level or a hydro system?', 'Application Inquiry', ARRAY['X-Bond Seamless Stone']::text[], ARRAY['Heated floor system']::text[], 'Excel Repository'),
    ('It says to use 1 part X-Bond Liquid and 2 ½ parts of X-Bond stone.', 'Scratch coat is 1:2 Finish coats are 1:2.5', 'Product Knowledge', ARRAY['X-Bond Seamless Stone']::text[], ARRAY[]::text[], 'Excel Repository'),
    ('Could you provide guidance on whether it is acceptable to make holes in the X-Bond material for hanging art on the walls? Could the holes cause cracking or splitting? If so, is it possible to repair the walls and what method is recommended?', 'Any walls coated in X-Bond Microcement should be treated like concrete when making holes to hang something. It should not cause splitting when done correctly. X-Bond bonds to any hard surface, including itself. Most repairs are done with a combination of sanding, apply X-Bond to fill/repair/level, sanding a bit to smooth out, and applying tinted sealer (That would be the matte Satin Stone most people are specifying nowadays. Gloss options available.) in a faux finishing/spraying manner to blend.', 'Technical Inquiry', ARRAY['X-Bond Seamless Stone']::text[], ARRAY[]::text[], 'Excel Repository'),
    ('What is the process for doing color match / a custom color?', 'This is typically done with the awarded installer with our guidance. You''d inform us of the color. We would provide any necessary suggestions (like darker colors may need double pigment or lighter colors may need to avoid a steel trowel to keep burnishing to a minimum, etc.) and they would proceed with a first round of samples for approval.', 'Application Inquiry', ARRAY['X-Bond Seamless Stone']::text[], ARRAY[]::text[], 'Excel Repository'),
    ('Is it possible to do a custom color?', 'Yes. Semco offers over 1000 base colors and will advise your awarded sub on how to make final adjustments as they make your submittal samples. X-Bond Microcement has too many color/texture/sheen options for us, the manufacturer, to create samples that subs have to duplicate.', 'General Inquiry', ARRAY['X-Bond Seamless Stone']::text[], ARRAY[]::text[], 'Excel Repository'),
    ('is it possible to use one of your sealers over existing Limewash paint for added cleanability and durability?', 'Sometimes! We have several options. You''d want your installer to test it first to see if it works. Or you''d the manufacturer of the limewash and ask them what they think based on the below descriptions: Semco Satin Stone - very matte, topical, very protective/chemical resistant, typically lasts minimum 10 years - is a 2 part, water based, polyurea. Semco Natural Shield - flat, penetrating, hydrophobic but not resistant to oils and many chemicals - Waterbased, silane siloxane.', 'Application Inquiry', ARRAY['X-Bond Seamless Stone']::text[], ARRAY['Limewash paint']::text[], 'Excel Repository'),
    ('cracks are visible which is the main concern of the owner', 'X-Bond Microcement is not mixed with water. It''s got it''s own polymer liquid that provides a lot more flexibility than any water mix materials. It''d also a chemical bond, not adhesion so it holds strong against surface movement from where it penetrates into cracks. See detail: https://www.semcosurfaces.com/s/Cracks-Joints-wider-14.pdf', 'Application Inquiry', ARRAY['X-Bond Seamless Stone']::text[], ARRAY[]::text[], 'Excel Repository'),
    ('Advantages & Disadvantages to the product', 'The straight answers are higher polymer content/more flexibility, integrally waterproof, chemical bond to any hard surface without grinding or demolition, unlimited design and texture options, any type of use (floors/walls, interior/ext, above/below grade, showers/pools), Longevity (30 year old product, water based from the beginning), no mesh/lathe required....', 'Product Knowledge', ARRAY['X-Bond Seamless Stone']::text[], ARRAY[]::text[], 'Excel Repository'),
    ('customer has a soaking tub with geo thermal sulfer water and asking if they can use xb/nat shield.', 'Sulfuric water and any cementious material isn''t the best mix and the suflur rapidly degrades cements. X-Bond will offer a better resistance than normal concrete or cement due to its polymer content, however I dont see a life span of more than 7 years at 1/8 of an inch', 'Technical Inquiry', ARRAY['X-Bond Seamless Stone']::text[], ARRAY[]::text[], 'Excel Repository'),
    ('I am looking for something similar to tadelakt.', 'X-Bond Corsa and Polished are the closest to the look of tadelakt.', 'General Inquiry', ARRAY['X-Bond Seamless Stone']::text[], ARRAY[]::text[], 'Excel Repository'),
    ('I have a request for a detail to tie XB into a slot drain. Can someone point me to where I can find it, please?', 'Shower Drain Details - Most the same, its the only one we have since most of the time its best to follow the detail from the company that makes the drain.', 'General Inquiry', ARRAY['X-Bond Seamless Stone']::text[], ARRAY[]::text[], 'Excel Repository'),
    ('What would be your suggestion for a gloss black coating that is going to last?', 'High Gloss and stronger than the single part Titan - maybe go solvent? We have one called Xtra Gloss. It can be tinted black.', 'Product Knowledge', ARRAY['X-Tra Gloss']::text[], ARRAY[]::text[], 'Excel Repository'),
    ('How much coverage does Xtreme Gloss give over ADA Safety Floor?', '100 sq ft per kit', 'Product Knowledge', ARRAY['Xtreme Gloss']::text[], ARRAY[]::text[], 'Excel Repository'),
    ('What is the shelf life for raw pigment?', 'The color is 6 months or so, since it''s organic pigment. The rest is 3 years if kept temperate and sealed. I kept your colors on the side in case you have to bump your schedule.', 'Product Knowledge', ARRAY['Raw Pigment']::text[], ARRAY[]::text[], 'Excel Repository'),
    ('Would it be okay to apply this material to a wall that has orange peel texture and paint already applied?', 'Yes! You''d need to apply an X-Bond Brown Coat to smooth the surface out. It would just take a little more material. Perhaps an average 1/16" or 1/8" to bring it flush, depending on how heavy the texture is now.', 'Application Inquiry', ARRAY['X-Bond Seamless Stone']::text[], ARRAY[]::text[], 'Excel Repository'),
    ('Would you recommend applying it straight to sheetrock with mud?', 'You can! X-Bond will bond directly to any hard surface. It would make it easier to have it primed first but that''s not required. It''s easier because then the X-Bond won''t be absorbed [and dry] as fast.', 'Application Inquiry', ARRAY['X-Bond Seamless Stone']::text[], ARRAY['Sheetrock']::text[], 'Excel Repository'),
    ('Any suggestions on how to fill these small holes, or should we just add more sealer to protect what flaked off?', 'If you plan to use more X-Bond to fix it, X-Bond bonds to anything including itself. If you plan to only use Satin Stone, it doesn''t bond to itself unless you rough it up. Or you can just barely touch up the tiny spots and try not to go over old Satin Stone.', 'Product Knowledge', ARRAY['X-Bond Seamless Stone']::text[], ARRAY[]::text[], 'Excel Repository'),
    ('We are wondering if microcement can be installed over rubber flooring?', 'Depends on the stability of the rubber, but it’s best to remove it, we can bond to it, but with it being very flexible applying a rigid and seamless product over is not optimal', 'Application Inquiry', ARRAY['X-Bond Seamless Stone']::text[], ARRAY['Rubber flooring']::text[], 'Excel Repository'),
    ('Hi, someone''s client wants more white than our DP XB. Is there a type of paint they can apply to X-Bond and then seal with Titan?', 'Any type of water based acrylic paint likely best paint to use, which s the usual type anyway then it can be sealed over with Titan or a semi-gloss', 'Application Inquiry', ARRAY['X-Bond Seamless Stone']::text[], ARRAY[]::text[], 'Excel Repository'),
    ('does XB contain lime?', 'Yes, nearly all cement does.', 'Product Knowledge', ARRAY['X-Bond Seamless Stone']::text[], ARRAY[]::text[], 'Excel Repository'),
    ('Can SLM handle spills of treated water at 160 degrees?', 'Spills, yes. Standing, No.', 'Application Inquiry', ARRAY['SEMCO Liquid Membrane']::text[], ARRAY[]::text[], 'Excel Repository'),
    ('Client is asking if they can apply XB over the caulk line on the glass shower door...? I thought the advice would be to remove it but I''m not positive and he doesn''t want to if he doesn''t have to', 'If for any reason that frame has to be changed, repaired, or anything XB of the caulking would need to be removed. So it’s dependent on the client/contractor. So the short, if the caulking is paintable (most are) it can be XB over. But usually we terminate to the caulking', 'Application Inquiry', ARRAY['X-Bond Seamless Stone']::text[], ARRAY[]::text[], 'Excel Repository'),
    ('I have a client that had a printed floor covering done. The picture is of sample material. The ink is an alcohol based. Would satin stone attach to the vinyl ok?', 'Test a small area first, it will stick but I''m concerned about it making the color bleed', 'Application Inquiry', ARRAY['X-Bond Seamless Stone']::text[], ARRAY['Vinyl']::text[], 'Excel Repository'),
    ('if someone says they used a magic trial for satin Stone and it was difficult and the pictures look like this does that mean they did not have enough volume? If the picture tells you anything please share with us. He used 4/5 of a satin kit on 900 ft, 1st coat. Sounds like he did not have enough product for the magic trowel coat, right?', 'When using the magic trowel on a full area its important to mix what you can apply as well as keep a wet edge, this appears that they mixed a full kit, poured it from one side to another, and tried to move it like they would a micro cement or epoxy, thats where they have areas that its likely saturated and other where they pull the material while it was already drying.. The shiny parts are where the product is still curing and likely going to take much longer as it could be a heavy applied spot. They should have used a maximum of 3 kits for the first coat when applied evenly, and the remaining 2 on the 2nd pass.', 'Application Inquiry', ARRAY['X-Bond Seamless Stone']::text[], ARRAY[]::text[], 'Excel Repository'),
    ('The wall is composed of new .625” high impact, mold resistant drywall. What is the preferred condition of the drywall prior to installation of the SEMCO product? Meaning do we mud, tape and finish the drywall as normal or leave it in an unaltered state?', 'For the drywall, we recommend mudding, taping, and a standard primer to limit absorption by the drywall drying our product out during installation. This will provide a smooth and stable surface for our product.', 'Application Inquiry', ARRAY['X-Bond Seamless Stone']::text[], ARRAY['Drywall']::text[], 'Excel Repository'),
    ('If there is a hard edge that I need to add a reglet to, around a door way. Do you have any recommendations?', 'Regarding the reglet around the doorway, we suggest tyng the waterproofing in by overlapping with Semco Liquid Membrane (SLM)and our crack suppression fabric. This will create a clean edge and allow for slight movement.', 'Application Inquiry', ARRAY['X-Bond Seamless Stone']::text[], ARRAY[]::text[], 'Excel Repository'),
    ('What would be the best sheathing/substrate (ie. permabase, greenboard or ?) be for your material in this spa? With it being new construction, they want to do whatever is best for the product.', 'The beauty of X-Bond is that it bonds to X, regardless of what it is. Any board or panel the architect or builder choose are suitable. X-Bond Microcement will provide waterproofing and finish, Semco Liquid Membrane and antifracture fabric are your vapor barrier and joint taping. Our shower detail covers any board or panel system: https://www.semcosurfaces.com/s/Shower-Detail-Concrete.pdf', 'Application Inquiry', ARRAY['X-Bond Seamless Stone']::text[], ARRAY[]::text[], 'Excel Repository'),
    ('How would Xbond liquid work over an old (1-2 year old) xylene stain?', 'Clean the surface with a neutral pH cleaner, and as always when going over a existing costing its best to start with a small section first', 'Application Inquiry', ARRAY['X-Bond Liquid']::text[], ARRAY['Xylene stain']::text[], 'Excel Repository'),
    ('Should the X-Bond Liquid be allowed to dry first before applying Liquid Membrane?', 'Yes', 'Application Inquiry', ARRAY['X-Bond Liquid']::text[], ARRAY[]::text[], 'Excel Repository'),
    ('What yield should I tell them for Xbond Liquid as a primer? Range is fine...', '350 - 400 for a single coat, variable based on porosity @ 1 coat', 'General Inquiry', ARRAY['X-Bond Liquid']::text[], ARRAY[]::text[], 'Excel Repository'),
    ('Can it be used in a garage? I’m worried about the weight of vehicles, wear and tear or stains.', 'Yes. The product is industrial grade and used under firetrucks regularly. This can be seen in our case studies: https://www.semcosurfaces.com/case-studies', 'Application Inquiry', ARRAY['X-Bond Seamless Stone']::text[], ARRAY[]::text[], 'Excel Repository'),
    ('What about earthquakes and cracking? Is it repairable if ever?', 'It''s always going to bond to itself. It''s 3x more flexible than any product you mix with water due to the fact that there''s a liquid polymer instead of water.', 'Application Inquiry', ARRAY['X-Bond Seamless Stone']::text[], ARRAY[]::text[], 'Excel Repository'),
    ('Since it’s a four phase project what about color matching issues 2-3 years later?', 'The awarded installer can make slight adjustments on site, as needed.', 'Application Inquiry', ARRAY['X-Bond Seamless Stone']::text[], ARRAY[]::text[], 'Excel Repository'),
    ('Should all of the product be purchased at once to ensure perfect color matching?', 'We use organic pigments, for maximum protection against UV, so they won''t last too far over 6 months.', 'General Inquiry', ARRAY['X-Bond Seamless Stone']::text[], ARRAY[]::text[], 'Excel Repository'),
    ('Shelf life, can it sit? Could the humidity in Hawaii interfere and affect the product?', 'Everything except for color lasts 3 years if kept dry and temperate.', 'Product Knowledge', ARRAY['X-Bond Seamless Stone']::text[], ARRAY[]::text[], 'Excel Repository'),
    ('I’m interested to know if you have an installer here on island? I haven’t been able to find one and I’ve been inquiring for almost a year. No one even knows what micro cement is here! Hawaii seems to be 3 years behind compared to the mainland!', 'Precision Flooring in Oahu, Justin Saniatan 808-439-2495 or Chara Hoe CNS Construction from Kauai cns.kauai@gmail.com 808-639-9091', 'Installer Inquiry', ARRAY['X-Bond Seamless Stone']::text[], ARRAY[]::text[], 'Excel Repository'),
    ('The home was built in the 60’s so the floor is definitely uneven with low spots that are noticeable when walking. What leveling preparation is recommended for the application?', 'If it''s a lot, use anything you deem appropriate as X-Bond bonds to every hard surface as long as it''s clean and pH neutral. If it''s under 1/4" you may choose to just use more X-Bond Microcement in the form of our Brown coat.', 'Technical Inquiry', ARRAY['X-Bond Seamless Stone']::text[], ARRAY[]::text[], 'Excel Repository'),
    ('Can I apply X-Bond Microcement directly to the Redgard waterproof coating?', 'Yes, you can go straight to redgard. You would start at Step 4 on this details as the Redgard replaces our Semco Liquid Membrane and taping: https://static1.squarespace.com/static/665d432a8da8ed6f609c038c/t/667ba6bd2579aa68d5bb390c/1719379651200/Shower+Detail+Concrete.pdf', 'Application Inquiry', ARRAY['X-Bond Seamless Stone']::text[], ARRAY['Waterproof coating']::text[], 'Excel Repository'),
    ('I have a customer who is asking if they applied only Titan Shield to a driveway would it fully protect it from hot tire marks etc. The driveway is currently concrete. Would they need to do scratch coat and primer for full protection or can they do solely Titan Shield?', 'Good for standard road vehicle traffic, hot tire marks are not from the floor or a sealant it from the tire, so tire marks are still going to occur over the top, the biggest difference is that it will be easier to clean. Now as an extended item there are lots of types of tires out there, the ones that can raise issues are racing/summer flats and off road tires. The summer tires are really soft and dont take much to heat up and when hot are usually at the melting point of rubber if right off the road and runs over the sealer it can stick the the sealer when cooled and then moved will remove the sealer. Then for off road tires the thread are very coarse and in events traction is low and turns on the sealer it can scratch the sealer', 'Application Inquiry', ARRAY['Titan Shield']::text[], ARRAY['Concrete']::text[], 'Excel Repository'),
    ('We had completed the installation of the final coat of the ADA Surface and were going to let it dry until Monday before sanding and then applying the satin stone sealer. No rain was predicted. The Semco surface is now marked with water stains. How do we remove them before applying the Satin Stone Sealer?', 'Unless it''s bubbling or peeling the X-Bond is in tact, just discolored from getting wet while curing. Here are some things to try: 1. Semco Prep D, Nulift & Stone Soap - test a small area first to see if it''s working. If not, clean the surface with Prep D and try one of the next 2 2. If that doesn''t work you''ll either spray more X-Bond ADA from a hopper gun over the existing 3. Or you can color the sealer to cover this up. Sealers have their own color activators. Do not use the one from X-Bond for sealer.', 'Technical Inquiry', ARRAY['X-Bond Seamless Stone']::text[], ARRAY[]::text[], 'Excel Repository'),
    ('Can the microcement assembly be applied over the ‘Laticrete 9235 waterproofing membrane? (Building Requirement) Can you confirm that it will not detach or chunks of it fall off in the shower stall because it cannot adhere properly to the ‘Laticrete’ membrane.', 'Yes, X-Bond Microcement has a history of applications over Laticrete 9235. It bonds chemically, and not by adhesion. As a manufacturer we warrant that it will bond directly to any hard surface that is clean and pH neutral.', 'Application Inquiry', ARRAY['X-Bond Seamless Stone']::text[], ARRAY['Ladicrete Waterproofing membrane']::text[], 'Excel Repository'),
    ('Can you please provide the maintenance instructions and how often it may need to be resealed or top coat reapplied.', 'Satin Stone is the required sealer for a shower. When applied to manufacturer''s specifications it''s expected to last a minimum of 10 years, which is featured on its webpage: https://www.semcosurfaces.com/satin-stone-sealer When resealing, the surface would get roughed up prior to new application. It''s maintained with any pH neutral cleaner. We offer one called Stone Soap.', 'Application Inquiry', ARRAY['Satin Stone']::text[], ARRAY[]::text[], 'Excel Repository'),
    ('Have you ever applied to AAC (Aereated Autoclave Concrete) walls or floors ?', 'X-Bond Microcement has been applied to every kind of board or block system you can think of. It just needs to be clean and pH neutral for bonding.', 'Application Inquiry', ARRAY['X-Bond Seamless Stone']::text[], ARRAY['Aereated Autoclave Concrete']::text[], 'Excel Repository'),
    ('What''s the best sealer to apply to a fiber glass tub?', 'Natural Shield. Matte Sealer CANNOT be used on tubs', 'Product Knowledge', ARRAY['Natural Shield']::text[], ARRAY['Fiberglass']::text[], 'Excel Repository'),
    ('Can this product be applied over asbestos tile?', 'Yes. X-Bond Microcement bonds chemically, to any hard surface, and not via standard adhesion.', 'Application Inquiry', ARRAY['X-Bond Seamless Stone']::text[], ARRAY['Asbestos Tile']::text[], 'Excel Repository'),
    ('how does it perform with regards to mold?', 'X-bond can be an encapsulator with all kinds of things like mold or asbestos. It can trap it in and prevent you from breathing it, but it won''t solve the problem', 'General Inquiry', ARRAY['X-Bond Seamless Stone']::text[], ARRAY[]::text[], 'Excel Repository'),
    ('What''s the best sealer to use in a steam room or sauna?', 'Satin Stone or Xtra Gloss. Other sealers won''t hold up to the moiusture and vapor of a sauna', 'General Inquiry', ARRAY['Satin Stone']::text[], ARRAY[]::text[], 'Excel Repository'),
    ('Full mesh vs just joints and seams?', 'Recommended to only apply fabric to joints and seams. Full meshing over X-BOND will actually reduce its flexibility', 'Technical Inquiry', ARRAY['Fabric Reinforcement']::text[], ARRAY[]::text[], 'Excel Repository'),
    ('Can the X-Bond Microcement handle 200 degrees of heat?', 'The X-Bond Microcement can handle up to 500 degrees of heat without any issues.', 'Technical Inquiry', ARRAY['X-Bond Seamless Stone']::text[], ARRAY[]::text[], 'Excel Repository'),
    ('Can I order 1: 5 gal container?', 'No, the minimum order for this product would be a 55 gallon drum or 55 gallon singles.', 'Product Knowledge', ARRAY['X-Tra Gloss']::text[], ARRAY[]::text[], 'Excel Repository'),
    ('What''s the curing time on a new concrete slab before applying X-BOND?', '28 days. The only way to bypass the 28 day curing time for a new concrete slab, would be to apply Natural Shield sealer at the 14-day mark, wait 3 to 4 days, then read the moisture level on the slab. If it reads 75% or lower, then you can use X-BOND.', 'Product Knowledge', ARRAY['X-Bond Seamless Stone']::text[], ARRAY['Concrete']::text[], 'Excel Repository'),
    ('We discovered that the paint is in the X Bond liquid primer, but when we started sanding areas with the recommended grit sand paper, it leaves dark colorations from the process. Is this normal?', 'Yes, because the color is throughout, when profiling to smooth its recommended to do an entire area versus just a isolated ones because it can change the overall look, natural shield would not enhance anything either', 'Technical Inquiry', ARRAY['X-Bond Seamless Stone']::text[], ARRAY[]::text[], 'Excel Repository'),
    ('The color does not match, what do I do?', 'First, ensure that there is a light turned on in the area. Second, ensure the product has meet the requirements of drying/curing time recommended. Third, check the packing slip and mix ratios/steps of how the product was applied.', 'Color', ARRAY['X-Bond Seamless Stone']::text[], ARRAY[]::text[], 'Excel Repository'),
    ('What is the difference between micro-bond and the liquid and what is the use for each since they look similar?', 'X-BOND Liquid and MicroBond have two entirely different purposes. X-BOND Liquid is to be mixed with X-BOND Stone, MicroBond, or used as a primer before applying skim coats. MicroBond is used to create a thinner layer to achieve an ultrasmooth surface. This should be the final coat after your skim coats', 'General Inquiry', ARRAY['X-Bond Seamless Stone']::text[], ARRAY[]::text[], 'Excel Repository'),
    ('How can adhesive be rmeoved prior to application?', 'Power Cleaner + Stone Soap', 'Product Knowledge', ARRAY['Stone Soap','Power Cleaner']::text[], ARRAY[]::text[], 'Excel Repository'),
    ('I have a 4” concrete slab getting poured and the x-bond will be applied on top. Do you have a recommendation for how long the slab needs to cure before install of your products, or any other recommendations around this type of installation?', 'The standard curing time for concrete surfaces is 28 days. If the process needs to be accelerated, there is a workaround: At the 14-day mark after installing, you can use our Natural Shield sealer (1 coat) to trap the moisture. After 4-5 days, if the moisture levels are read and below 75%, you''re good to use X-BOND on the substrate.', 'Application Inquiry', ARRAY['X-Bond Seamless Stone']::text[], ARRAY['Concrete']::text[], 'Excel Repository');

COMMIT;

